          "Meta’s creator-safety announcement from 2024 describes tools for removing spam followers in bulk. This is dated platform-tool context, not identical present access for every account or independent brand proof that each identified or removed account is fake.\n\nIf an appropriate owner reports a moderation action, retain its object, time and confirmed scope. A falling total alone cannot establish the exact number of bots removed, and resumed growth cannot establish that every anomaly ended. Review the management action and data interpretation separately.\n\nA new observation reference can follow a documented action if the reason and remaining unknowns are stated. It describes how the next period will be observed; it does not retrospectively certify every earlier follower. Avoid letting a cleaned label remove the evidence boundaries the report needs. A limited action record is useful precisely because it says what was checked without silently expanding into a finding about all previous activity."
