          "选择新起点前，写明它服务哪个任务、采用何种字段与来源、比较窗口如何确定，以及与原始记录有什么不可比条件。应由合适的业务负责人理解并采用，而不是分析人员在结果出现后挑最有利的一对数字。\n\n合理的理由可能是下一阶段按新定义开始记录，或某个可用来源从明确时点起恢复。但这不说明旧区间已经失效到可以完全忘记，也不代表新窗口就没有其他影响。原窗口与新窗口可以并列，分别说明用途与限制。\n\n如果资料尚不足以建立新参考，可以继续保留已有描述，缩小比较结论，或等待适当材料。不要为了满足一张报表的固定格式，强行制造一个“真实粉丝基线”。参考点是一项管理选择，必须能被下一位同事理解和复核，而不是隐藏在最终增长率背后的自由裁量。",
          "Before selecting a new reference, state the task, field, source, comparison window and differences from the original observation. An appropriate business owner should understand and adopt it, rather than an analyst selecting the most favorable pair after seeing the outcome.\n\nA defensible reason might be beginning a new phase under a revised definition or an identified source becoming available from a particular time. That does not make the earlier period forgettable or eliminate other influences on the new window. Old and new references can coexist with distinct purposes and limitations.\n\nIf evidence is insufficient for another reference, retain the existing description, narrow the conclusion or wait for appropriate material. A reporting template is not a reason to invent an authentic-follower baseline. The reference is a management choice that another colleague should be able to understand and review, not hidden discretion behind the final growth percentage. Documenting the choice first also helps prevent a later stakeholder from interpreting the new window as an independent verification exercise."
