          "Suppose one account has 12,000 followers at the original observation, 14,000 at an intermediate point and 14,600 later. A free-follower claim was discussed in between, but its cause remains unconfirmed. These are hypothetical figures, not creator data or an industry benchmark.\n\nThe net change from 14,000 to 14,600 is 600. Using the intermediate total as denominator gives a descriptive change rate of 600 ÷ 14,000 × 100%, approximately 4.29%. From 12,000 to 14,600, the net change is 2,600. They concern different windows, not competing answers from which to select the better-looking report. Neither amount is a verified count of newly acquired real people.\n\nIf the next phase references 14,000, retain 12,000 and the intervening conditions. Do not subtract an assumed 2,000 and certify the remainder authentic. The arithmetic can be checked while cause and composition remain unresolved. Those are different levels of certainty, and a responsible report should make that difference visible."
