          "The UK Magenta Book evaluation guide bases impact evaluation on suitable comparison and counterfactual evidence among other conditions. Apply that methodological boundary here: an observed change does not establish what would have happened without the campaign, and choosing a new starting reference does not create causal evidence.\n\nThe hypothetical net increase of 600 should therefore not become incremental followers delivered by one asset, much less proof that a free service works. Other content, existing exposure, platform actions and observation conditions can change together. No impact evaluation was performed here, and the article does not recommend exposing other accounts to artificial engagement as an experiment.\n\nIf additional campaign impact is the business question, involve appropriate analysts in a proportionate research design with explicit assumptions and limits. Ordinary reporting can still describe change honestly. Acknowledging that causality is unproven does not make observations useless. It identifies the type of decision the current evidence can support without borrowing certainty from a different evaluation method."
