          "Use the social media metrics decision framework to retain source, window, unit and missingness. An unavailable point is unavailable, not zero. An unknown cause is unknown, not a composition estimate guessed from avatars, countries or one interaction ratio.\n\nShow the original observations, changed windows and new recording arrangement while identifying noncomparable parts. If the decision only concerns whether publication occurred, there is no need to add follower growth as a performance verdict. Different tasks require different evidence; not every report needs one combined success score.\n\nPreserve attribution of the free-growth claim itself. An advertisement, creator self-description, brand observation and independent evidence are not interchangeable sources. Separating them lets an owner take risk seriously without expanding suspicion into an established conclusion of dishonesty about a particular person. The report can then explain what needs reviewing rather than manufacture a numerical answer to every concern. This is especially useful for colleagues who never saw the original discussion and might otherwise inherit an overconfident summary."
