    "summary": [
      "为达人合作建立 Facebook 主页，不只是填名称和上传图片，还要让观众分清谁主办、谁参与、活动条件在哪里，以及项目结束后谁继续负责。",
      "A Facebook Page for creator collaboration needs more than a name and image: identify organizer, participants, conditions and who remains responsible after the project."
    ],
    "metaDescription": [
      "Create Facebook page 怎样服务达人合作：准备公共身份、项目信息与联系路径，核对账号权限和内容使用，安排发布前检查及活动后维护。",
      "Create a Facebook Page around a creator campaign with clear public identity, project information, contact routes, scoped access and an after-campaign maintenance plan."
    ],
    "answer": [
      "为达人合作创建 Facebook 主页时，先确定它代表谁、观众为什么需要它，以及谁在活动结束后维护。准备获准名称与图片、准确项目说明、相关条件和明确联系路径；由适当负责人通过 Facebook 当前官方流程创建并检查实际访问权限。不要用创作者姓名暗示未确认的代言关系，也不要把新主页当作自动带来触达的工具。创建完成只是起点，公开信息准确、可访问和有人负责，才使它成为可靠的合作承接位置。",
      "Before creating a Facebook Page for a creator campaign, decide whom it represents, why the audience needs it and who maintains it afterward. Prepare an authorized name and images, accurate project information, applicable conditions and a clear contact route. An appropriate owner should use Facebook’s current official creation process and verify actual access. Do not imply an unconfirmed endorsement through a creator’s name or treat a new Page as an automatic distribution engine. Creation is a starting point; accurate, accessible information and continuing responsibility make it a useful campaign destination."
    ],
